#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; STATE="$ROOT/.framework/hoard-deploy-state"; [[ -d "$STATE" ]] || { echo 'HOARD ROLLBACK VERIFY FAILED: deploy state missing' >&2; exit 1; }; PREFIX="$(cat "$STATE/prefix" 2>/dev/null || printf '%s' "${PREFIX:-$HOME/.local}")"
fail(){ echo "HOARD ROLLBACK VERIFY FAILED: $*" >&2; exit 1; }; verify_restored(){ local key="$1" path="$2" present; present="$(cat "$STATE/${key}.present" 2>/dev/null || echo 0)"; if [[ "$present" == 1 ]]; then [[ -e "$path" ]] || fail "$key missing after rollback: $path"; cmp -s "$STATE/backup/$key" "$path" || fail "$key differs from pre-deploy snapshot: $path"; else [[ ! -e "$path" ]] || fail "$key should not remain after rollback: $path"; fi; }
verify_restored binary "$PREFIX/bin/hoard"; verify_restored desktop "$PREFIX/share/applications/hoard.desktop"; verify_restored icon "$PREFIX/share/icons/hicolor/scalable/apps/hoard.svg"; verify_restored theme "$PREFIX/share/hoard/themes/hoard.toml"; verify_restored config-theme "$HOME/.config/hoard/themes/hoard.toml"; verify_restored settings "$HOME/.config/hoard/settings.toml"; verify_restored update "$HOME/.config/hoard/update.toml"; verify_restored framework-lock "$PREFIX/share/hoard/build-info/framework-lock.json"; verify_restored cargo-lock "$PREFIX/share/hoard/build-info/Cargo.lock"; verify_restored evidence "$PREFIX/share/hoard/build-info/evidence.json"; verify_restored installed-sha "$PREFIX/share/hoard/build-info/installed.sha256"; verify_restored build-id "$PREFIX/share/hoard/build-info/build-id"
PREV_MIME="$(cat "$STATE/previous-mime" 2>/dev/null || true)"; if [[ -n "$PREV_MIME" ]] && command -v xdg-mime >/dev/null 2>&1; then CURRENT_MIME="$(xdg-mime query default inode/directory 2>/dev/null || true)"; [[ "$CURRENT_MIME" == "$PREV_MIME" ]] || fail "directory handler not restored: expected=$PREV_MIME actual=${CURRENT_MIME:-<empty>}"; fi
if [[ "$(cat "$STATE/binary.present" 2>/dev/null || echo 0)" == 1 ]]; then "$PREFIX/bin/hoard" --self-test; "$ROOT/scripts/runtime-smoke.sh" "$PREFIX/bin/hoard"; fi
echo 'HOARD ROLLBACK VERIFICATION PASSED'
